@startuml

class User {
  + Id : string
}

class Doctor extends User {
  + GraduationYear : date
  + FieldOfActivity : string
  + CreateSchedule()
}

class Patient extends User {
  + BookAppointment()
}

class Hospital {
  + Name : string
}

class Office {
  + Id : string
  + Name : string
}

class Schedule {
  + Id : string
  + StartDate : date
  + EndDate : date
}

class Appointment {
  + Id : string
  + StartDate : datetime
  + EndDate : datetime
}

class BloodTest {
  + Duration : int
}

class Consultation {
  + Duration : int
}

class Surgery {
  + Duration : int
}

Hospital "1" *-- "*" Office
Doctor "1..*" -- "1..*" Office : applies to
Doctor "1" -- "1" Schedule : creates
Office "1" -- "1" Schedule : has
Schedule "1" *-- "*" Appointment
Patient "1" -- "*" Appointment : books
Appointment <|-- BloodTest
Appointment <|-- Consultation
Appointment <|-- Surgery

@enduml

